      // keeps the panel open across multiple push cycles).
      return (
        '<div class="alp-sec-row" data-alp-key="' + s.key + '" data-alp-cur-ver="' + _ebEsc(curV) + '" style="display:grid; grid-template-columns:auto 1fr auto; gap:10px; align-items:center; padding:8px 12px; background:' + stripe + '; border-bottom:1px solid #f1f5f9;">' +
